<script lang="ts">import { MasonryRoot,MasonryVirtualViewport } from '@fex-design/svelte/primitive/masonry';import Button from '@fex-design/svelte/ui/button';import { onMount } from 'svelte';import { virtualMasonryItems,type MasonryDemoItem } from './data';let host:HTMLDivElement,expanded:string[]=$state([]),mounted=$state(0),offset=$state(0);const update=(element:HTMLElement)=>{offset=element.scrollTop;mounted=element.querySelectorAll('[data-index]').length};const scrollTo=(index:number)=>{const viewport=host.querySelector<HTMLElement>('[data-slot="masonry-virtual-viewport"]');if(viewport)viewport.scrollTo({top:index/virtualMasonryItems.length*(viewport.scrollHeight-viewport.clientHeight),behavior:'smooth'})};onMount(()=>requestAnimationFrame(()=>{const viewport=host.querySelector<HTMLElement>('[data-slot="masonry-virtual-viewport"]');if(viewport)update(viewport)}))</script>
{#snippet content(item:MasonryDemoItem,index:number)}<article class="rounded-md border border-border bg-background p-space-md" style:min-height={`${expanded.includes(item.id)?item.height+100:item.height}px`}><strong>{item.title}</strong><p class="mt-2 text-xs text-muted-foreground">索引 {index} · TanStack measured lane</p><Button class="mt-2" size="sm" variant="outline" onclick={()=>expanded=expanded.includes(item.id)?expanded.filter(id=>id!==item.id):[...expanded,item.id]}>{expanded.includes(item.id)?'收起动态内容':'展开动态内容'}</Button></article>{/snippet}
<div bind:this={host} class="grid gap-space-md"><div class="flex flex-wrap items-center gap-space-sm"><span class="text-sm">总数 5,000 · 当前挂载 {mounted||'…'} · scrollTop {Math.round(offset)}</span><Button size="sm" variant="outline" onclick={()=>scrollTo(0)}>首项</Button><Button size="sm" variant="outline" onclick={()=>scrollTo(499)}>第 500 项</Button><Button size="sm" variant="outline" onclick={()=>scrollTo(4999)}>末项</Button></div><MasonryRoot columns={{minColumnWidth:180,max:4}} gap={12}><MasonryVirtualViewport items={virtualMasonryItems} getItemKey={item=>item.id} estimateSize={item=>item.height} height={420} class="rounded-md border border-border" onscroll={event=>update(event.currentTarget)} children={content}/></MasonryRoot></div>
